// The engine's copy of `serve/grammar/matcher.py`'s vocabulary build. See the
// header for what it produces and why.
//
// Two JSON files are read, both generated by the pack's own exporter and both
// trivial in shape: `vocab.json` is an object of string -> id, `token_type.json`
// is an array of ids. A JSON library for two shapes is not worth a dependency, so
// the reader below understands exactly those two and reads JSON strings properly
// (escapes and `\u`, including surrogate pairs), because 1,234 of gyro_l's tokens
// carry an escape and a misread token would constrain the wrong id.

#include "strata/grammar/vocabulary.hpp"

#include <cstdio>
#include <cstring>
#include <fstream>
#include <sstream>

namespace strata {
namespace grammar {
namespace {

// ---------------------------------------------------------------- byte alphabet
// The GPT-2 byte encoder: bytes 0x21..0x7E, 0xA1..0xAC, 0xAE..0xFF stand for
// themselves; the rest (space, control characters, the two holes) are moved up to
// 256+n, so every byte is one printable character and the mapping is reversible.
struct ByteAlphabet {
    // codepoint -> byte, or 0xFFFF when the codepoint is not part of the alphabet.
    uint16_t to_byte[0x200];

    ByteAlphabet() {
        for (uint32_t i = 0; i < 0x200; ++i) to_byte[i] = 0xFFFF;
        bool self[256] = {};
        for (int b = 0x21; b <= 0x7E; ++b) self[b] = true;
        for (int b = 0xA1; b <= 0xAC; ++b) self[b] = true;
        for (int b = 0xAE; b <= 0xFF; ++b) self[b] = true;
        for (int b = 0; b < 256; ++b) {
            if (self[b]) to_byte[b] = (uint16_t) b;
        }
        uint32_t next = 0;
        for (int b = 0; b < 256; ++b) {
            if (!self[b]) to_byte[256 + next++] = (uint16_t) b;
        }
    }
};

void append_utf8(std::string& s, uint32_t cp) {
    if (cp < 0x80) {
        s.push_back((char) cp);
    } else if (cp < 0x800) {
        s.push_back((char) (0xC0 | (cp >> 6)));
        s.push_back((char) (0x80 | (cp & 0x3F)));
    } else if (cp < 0x10000) {
        s.push_back((char) (0xE0 | (cp >> 12)));
        s.push_back((char) (0x80 | ((cp >> 6) & 0x3F)));
        s.push_back((char) (0x80 | (cp & 0x3F)));
    } else {
        s.push_back((char) (0xF0 | (cp >> 18)));
        s.push_back((char) (0x80 | ((cp >> 12) & 0x3F)));
        s.push_back((char) (0x80 | ((cp >> 6) & 0x3F)));
        s.push_back((char) (0x80 | (cp & 0x3F)));
    }
}

// ---------------------------------------------------------------------- reader
// A cursor over the whole file. Every helper leaves the cursor unmoved on failure,
// so the first thing that goes wrong is the thing reported.
struct Reader {
    const char* p;
    const char* end;
    std::string what;  // a description of where it stopped, for the message

    bool at_end() const { return p >= end; }

    void skip_ws() {
        while (p < end && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) ++p;
    }

    bool expect(char c) {
        skip_ws();
        if (p >= end || *p != c) {
            fail(std::string("expected '") + c + "'");
            return false;
        }
        ++p;
        return true;
    }

    bool peek(char c) {
        skip_ws();
        return p < end && *p == c;
    }

    void fail(const std::string& why) {
        if (what.empty()) what = why;
    }

    bool read_u16(uint32_t& v) {
        v = 0;
        int n = 0;
        while (p + 4 <= end && n < 4) {
            char c = *p;
            uint32_t d = 0;
            if (c >= '0' && c <= '9') d = (uint32_t) (c - '0');
            else if (c >= 'a' && c <= 'f') d = (uint32_t) (c - 'a' + 10);
            else if (c >= 'A' && c <= 'F') d = (uint32_t) (c - 'A' + 10);
            else break;
            v = (v << 4) | d;
            ++p;
            ++n;
        }
        if (n != 4) {
            fail("a \\u escape without four hex digits");
            return false;
        }
        return true;
    }

    // A JSON string, as codepoints.  `vocab.json`'s keys are the only strings read.
    bool read_string(std::vector<uint32_t>& out) {
        out.clear();
        skip_ws();
        if (p >= end || *p != '"') {
            fail("expected a string");
            return false;
        }
        ++p;
        while (true) {
            if (p >= end) {
                fail("a string that never ends");
                return false;
            }
            unsigned char c = (unsigned char) *p;
            if (c == '"') {
                ++p;
                return true;
            }
            if (c == '\\') {
                ++p;
                if (p >= end) {
                    fail("a string ending in a backslash");
                    return false;
                }
                char e = *p++;
                switch (e) {
                    case '"': out.push_back('"'); break;
                    case '\\': out.push_back('\\'); break;
                    case '/': out.push_back('/'); break;
                    case 'b': out.push_back('\b'); break;
                    case 'f': out.push_back('\f'); break;
                    case 'n': out.push_back('\n'); break;
                    case 'r': out.push_back('\r'); break;
                    case 't': out.push_back('\t'); break;
                    case 'u': {
                        uint32_t hi = 0;
                        if (!read_u16(hi)) return false;
                        // A pair of escapes is one codepoint above the BMP.
                        if (hi >= 0xD800 && hi <= 0xDBFF && p + 1 < end && p[0] == '\\' && p[1] == 'u') {
                            const char* save = p;
                            p += 2;
                            uint32_t lo = 0;
                            if (read_u16(lo) && lo >= 0xDC00 && lo <= 0xDFFF) {
                                out.push_back(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00));
                                break;
                            }
                            p = save;
                        }
                        out.push_back(hi);
                        break;
                    }
                    default:
                        fail(std::string("an unknown escape \\") + e);
                        return false;
                }
                continue;
            }
            if (c < 0x20) {
                fail("a raw control character in a string");
                return false;
            }
            // Raw UTF-8: decode one sequence to a codepoint.
            uint32_t cp = 0;
            int extra = 0;
            if (c < 0x80) {
                cp = c;
            } else if ((c & 0xE0) == 0xC0) {
                cp = c & 0x1F;
                extra = 1;
            } else if ((c & 0xF0) == 0xE0) {
                cp = c & 0x0F;
                extra = 2;
            } else if ((c & 0xF8) == 0xF0) {
                cp = c & 0x07;
                extra = 3;
            } else {
                fail("invalid UTF-8 in a string");
                return false;
            }
            ++p;
            for (int i = 0; i < extra; ++i) {
                if (p >= end || ((unsigned char) *p & 0xC0) != 0x80) {
                    fail("truncated UTF-8 in a string");
                    return false;
                }
                cp = (cp << 6) | ((unsigned char) *p & 0x3F);
                ++p;
            }
            out.push_back(cp);
        }
    }

    bool read_uint(uint32_t& v) {
        skip_ws();
        if (p >= end || *p < '0' || *p > '9') {
            fail("expected a number");
            return false;
        }
        v = 0;
        while (p < end && *p >= '0' && *p <= '9') {
            v = v * 10 + (uint32_t) (*p - '0');
            ++p;
        }
        return true;
    }
};

bool read_file(const std::string& path, std::string& text, std::string& err) {
    std::ifstream in(path, std::ios::binary);
    if (!in) {
        err = path + ": cannot be opened";
        return false;
    }
    std::ostringstream ss;
    ss << in.rdbuf();
    text = ss.str();
    if (text.empty()) {
        err = path + ": is empty";
        return false;
    }
    return true;
}

// `{"<text>": <id>, ...}` - the id is where the token lives, so the text is stored
// by id and the count comes from the number of pairs.
bool read_vocab_json(const std::string& path, std::vector<std::vector<uint32_t>>& texts, std::string& err) {
    std::string body;
    if (!read_file(path, body, err)) return false;
    Reader r{body.data(), body.data() + body.size(), {}};
    if (!r.expect('{')) {
        err = path + ": " + r.what;
        return false;
    }
    uint32_t seen = 0;
    bool first = true;
    while (true) {
        if (r.peek('}')) {
            r.expect('}');
            break;
        }
        if (!first && !r.expect(',')) {
            err = path + ": " + r.what;
            return false;
        }
        first = false;
        std::vector<uint32_t> text;
        if (!r.read_string(text)) {  // the key: the token's text
            err = path + ": " + r.what;
            return false;
        }
        if (!r.expect(':')) {
            err = path + ": " + r.what;
            return false;
        }
        uint32_t id = 0;
        if (!r.read_uint(id)) {
            err = path + ": " + r.what;
            return false;
        }
        if (id > 100000000u) {
            err = path + ": id out of range";
            return false;
        }
        if (texts.size() <= id) texts.resize(id + 1);
        texts[id] = text;
        ++seen;
    }
    if (seen != texts.size()) {
        err = path + ": " + std::to_string(seen) + " entries for " + std::to_string(texts.size()) + " ids";
        return false;
    }
    return true;
}

// `[<id>, <id>, ...]` - one type per id, in id order.
bool read_type_json(const std::string& path, std::vector<uint32_t>& types, std::string& err) {
    std::string body;
    if (!read_file(path, body, err)) return false;
    Reader r{body.data(), body.data() + body.size(), {}};
    if (!r.expect('[')) {
        err = path + ": " + r.what;
        return false;
    }
    bool first = true;
    while (true) {
        if (r.peek(']')) {
            r.expect(']');
            break;
        }
        if (!first && !r.expect(',')) {
            err = path + ": " + r.what;
            return false;
        }
        first = false;
        uint32_t v = 0;
        if (!r.read_uint(v)) {
            err = path + ": " + r.what;
            return false;
        }
        types.push_back(v);
    }
    return true;
}

std::string join(const std::string& dir, const char* name) {
    if (dir.empty()) return name;
    if (dir.back() == '/') return dir + name;
    return dir + "/" + name;
}

}  // namespace

bool load_vocabulary(const std::string& dir, Vocabulary& out, std::string& err) {
    out = Vocabulary{};
    const std::string vocab_path = join(dir, "vocab.json");
    const std::string types_path = join(dir, "token_type.json");

    std::vector<std::vector<uint32_t>> texts;
    if (!read_vocab_json(vocab_path, texts, err)) return false;
    std::vector<uint32_t> types;
    if (!read_type_json(types_path, types, err)) return false;
    if (types.size() != texts.size()) {
        err = dir + ": vocab.json has " + std::to_string(texts.size()) + " ids, token_type.json " +
              std::to_string(types.size());
        return false;
    }

    static const ByteAlphabet alphabet;
    const uint32_t n = (uint32_t) texts.size();
    out.lens.assign(n, 0);
    out.bytes.clear();
    size_t total = 0;
    for (uint32_t i = 0; i < n; ++i) total += texts[i].size() + 1;  // +1 for a special's 0xFF
    out.bytes.reserve(total);

    bool have_eos = false;
    for (uint32_t i = 0; i < n; ++i) {
        const std::vector<uint32_t>& text = texts[i];
        const size_t before = out.bytes.size();
        const bool special = types[i] == 3 || types[i] == 4;  // CONTROL, USER_DEFINED
        if (special) {
            out.bytes.push_back(0xFF);  // how the grammar names a special token
            std::string utf8;
            for (uint32_t cp : text) append_utf8(utf8, cp);
            out.bytes.insert(out.bytes.end(), utf8.begin(), utf8.end());
            const char* eos_text = "<|im_end|>";
            if (utf8 == eos_text) {
                out.eos = i;
                have_eos = true;
            }
            ++out.special_count;
        } else {
            for (uint32_t cp : text) {
                if (cp >= 0x200 || alphabet.to_byte[cp] == 0xFFFF) {
                    err = vocab_path + ": token " + std::to_string(i) + " has a character outside the byte alphabet";
                    return false;
                }
                out.bytes.push_back((uint8_t) alphabet.to_byte[cp]);
            }
        }
        out.lens[i] = (uint32_t) (out.bytes.size() - before);
    }
    if (!have_eos) {
        err = types_path + ": no <|im_end|> token, so there is no end of turn to constrain";
        return false;
    }
    return true;
}

}  // namespace grammar
}  // namespace strata
